{"command":"cat <<'EOF' > src/main.rs
mod color;
use color::Color;
use std::env;
use std::io::{self, BufRead};

include!("colors_def.rs");

fn parse_color(s: &str) -> Option<Color> {
    if s.starts_with('#') {
        let hex = &s[1..];
        if hex.len() == 3 {
            let r = u8::from_str_radix(&hex[0..1], 16).ok()? * 17;
            let g = u8::from_str_radix(&hex[1..2], 16).ok()? * 17;
            let b = u8::from_str_radix(&hex[2..3], 16).ok()? * 17;
            return Some(Color::from_rgb(r, g, b));
        } else if hex.len() == 6 {
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            return Some(Color::from_rgb(r, g, b));
        } else if hex.len() == 8 {
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            let a = u8::from_str_radix(&hex[6..8], 16).ok()?;
            return Some(Color::new(r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0, a as f64 / 255.0));
        }
    }

    if let Some(rgb) = get_color_by_name(s) {
        return Some(Color::from_rgb(rgb[0], rgb[1], rgb[2]));
    }

    // TODO: support other formats like rgb(), hsl(), etc.
    None
}

fn format_color(color: &Color, format_type: &str) -> String {
    match format_type {
        "hex" => {
            let (r, g, b, a) = color.to_rgba_u8();
            if a == 255 {
                format!("#{:02x}{:02x}{:02x}", r, g, b)
            } else {
                format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, a)
            }
        }
        "rgb" => {
            let (r, g, b, a) = color.to_rgba_u8();
            if a == 255 {
                format!("rgb({}, {}, {})", r, g, b)
            } else {
                let alpha = (color.a * 1000.0).round() / 1000.0;
                format!("rgba({}, {}, {}, {})", r, g, b, alpha)
            }
        }
        "hsl" => {
            let (h, s, l) = color.to_hsl();
            format!("hsl({:.0}, {:.1}%, {:.1}%)", h, s * 100.0, l * 100.0)
        }
        _ => format!("unsupported format"),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: pastel <command> [args]");
        return;
    }

    let command = &args[1];
    match command.as_str() {
        "format" => {
            let format_type = if args.len() > 2 { &args[2] } else { "hex" };
            let colors = if args.len() > 3 {
                args[3..].to_vec()
            } else {
                let stdin = io::stdin();
                stdin.lock().lines().filter_map(|line| line.ok()).collect()
            };

            for color_str in colors {
                if let Some(color) = parse_color(&color_str) {
                    println!("{}", format_color(&color, format_type));
                }
            }
        }
        _ => println!("Unknown command: {}", command),
    }
}
