        let a = 500.0 * (f(x / x_n) - f(y / y_n));
        let b = 200.0 * (f(y / y_n) - f(z / z_n));

        (l, a, b)
    }

    pub fn to_oklab(&self) -> (f64, f64, f64) {
        let r = self.to_linear(self.r);
        let g = self.to_linear(self.g);
        let b = self.to_linear(self.b);

        let l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
        let m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
        let s = 0.0883024619 * r + 0.2817188501 * g + 0.6299787041 * b;

        let l_ = l.powf(1.0 / 3.0);
        let m_ = m.powf(1.0 / 3.0);
        let s_ = s.powf(1.0 / 3.0);

        (
            0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
            1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
            0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
        )
    }

    pub fn to_lch(&self) -> (f64, f64, f64) {
        let (l, a, b) = self.to_lab();
        let c = (a * a + b * b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h < 0.0 { h += 360.0; }
        (l, c, h)
    }

    pub fn to_oklch(&self) -> (f64, f64, f64) {
        let (l, a, b) = self.to_oklab();
        let c = (a * a + b * b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h < 0.0 { h += 360.0; }
        (l, c, h)
    }

    fn to_linear(&self, c: f64) -> f64 {
        if c <= 0.04045 {
            c / 12.92
        } else {
            ((c + 0.055) / 1.055).powf(2.4)
        }
    }

    pub fn luminance(&self) -> f64 {
        0.2126729 * self.to_linear(self.r) + 0.7151522 * self.to_linear(self.g) + 0.0721750 * self.to_linear(self.b)
    }
}
