{"command":"cat <<'EOF' > src/main.rs
mod color;
use color::Color;
use std::env;
use std::io::{self, BufRead, IsTerminal};

include!("colors_def.rs");

fn parse_color(s: &str) -> Option<Color> {
    let s = s.trim();
    if s.is_empty() { return None; }
    if s.starts_with('#') {
        let hex = &s[1..];
        if hex.len() == 3 {
            let r = u8::from_str_radix(&hex[0..1], 16).ok()? * 17;
            let g = u8::from_str_radix(&hex[1..2], 16).ok()? * 17;
            let b = u8::from_str_radix(&hex[2..3], 16).ok()? * 17;
            return Some(Color::from_rgb(r, g, b));
        } else if hex.len() == 6 {
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            return Some(Color::from_rgb(r, g, b));
        } else if hex.len() == 8 {
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            let a = u8::from_str_radix(&hex[6..8], 16).ok()?;
            return Some(Color::new(r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0, a as f64 / 255.0));
        }
    }

    if let Some(rgb) = get_color_by_name(s) {
        return Some(Color::from_rgb(rgb[0], rgb[1], rgb[2]));
    }

    if (s.starts_with("rgb(") || s.starts_with("rgba(")) && s.ends_with(')') {
        let start = if s.starts_with("rgba(") { 5 } else { 4 };
        let parts: Vec<&str> = s[start..s.len()-1].split(',').map(|p| p.trim()).collect();
        if parts.len() >= 3 {
            let r = parts[0].parse::<u8>().ok()?;
            let g = parts[1].parse::<u8>().ok()?;
            let b = parts[2].parse::<u8>().ok()?;
            let mut color = Color::from_rgb(r, g, b);
            if parts.len() == 4 {
                color.a = parts[3].parse::<f64>().ok()?;
            }
            return Some(color);
        }
    }

    if !s.starts_with('#') && (s.len() == 6 || s.len() == 3 || s.len() == 8) {
        if let Some(c) = parse_color(&format!("#{}", s)) {
            return Some(c);
        }
    }

    None
}

fn format_color(color: &Color, format_type: &str) -> String {
    match format_type {
        "hex" => {
            let (r, g, b, a) = color.to_rgba_u8();
            if a == 255 {
                format!("#{:02x}{:02x}{:02x}", r, g, b)
            } else {
                format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, a)
            }
        }
        "rgb" => {
            let (r, g, b, a) = color.to_rgba_u8();
            if a == 255 {
                format!("rgb({}, {}, {})", r, g, b)
            } else {
                let alpha = (color.a * 1000.0).round() / 1000.0;
                format!("rgba({}, {}, {}, {})", r, g, b, alpha)
            }
        }
        "hsl" => {
            let (h, s, l) = color.to_hsl();
            format!("hsl({:.0}, {:.1}%, {:.1}%)", h, s * 100.0, l * 100.0)
        }
        "lab" => {
            let (l, a, b) = color.to_lab();
            format!("Lab({:.0}, {:.0}, {:.0})", l, a, b)
        }
        "oklab" => {
            let (l, a, b) = color.to_oklab();
            format!("OkLab({:.4}, {:.4}, {:.4})", l, a, b)
        }
        "lch" => {
            let (l, c, h) = color.to_lch();
            format!("LCh({:.0}, {:.0}, {:.0})", l, c, h)
        }
        "oklch" => {
            let (l, c, h) = color.to_oklch();
            format!("OkLCh({:.4}, {:.4}, {:.4})", l, c, h)
        }
        "luminance" => {
            format!("{:.3}", color.luminance())
        }
        "name" => {
            for (name, rgb) in ALL_COLORS {
                let c = Color::from_rgb(rgb[0], rgb[1], rgb[2]);
                if (c.r - color.r).abs() < 0.001 && (c.g - color.g).abs() < 0.001 && (c.b - color.b).abs() < 0.001 {
                    return name.to_string();
                }
            }
            "unknown".to_string()
        }
        _ => format!("unsupported format"),
    }
