impl Color {
    pub fn from_xyz(x: f64, y: f64, z: f64) -> Self {
        let r_lin = 3.2404542 * x - 1.5371385 * y - 0.4985314 * z;
        let g_lin = -0.9692660 * x + 1.8760108 * y + 0.0415560 * z;
        let b_lin = 0.0556434 * x - 0.2040259 * y + 1.0572252 * z;

        Color::new(
            Self::from_linear(r_lin),
            Self::from_linear(g_lin),
            Self::from_linear(b_lin),
            1.0
        )
    }

    pub fn from_lab(l: f64, a: f64, b: f64) -> Self {
        let x_n = 0.95047;
        let y_n = 1.00000;
        let z_n = 1.08883;

        let f_inv = |t: f64| {
            if t > 6.0 / 29.0 {
                t.powi(3)
            } else {
                3.0 * (6.0 / 29.0f64).powi(2) * (t - 4.0 / 29.0)
            }
        };

        let l_ = (l + 16.0) / 116.0;
        let x = x_n * f_inv(l_ + a / 500.0);
        let y = y_n * f_inv(l_);
        let z = z_n * f_inv(l_ - b / 200.0);

        Self::from_xyz(x, y, z)
    }

    fn from_linear(c: f64) -> f64 {
        if c <= 0.0031308 {
            12.92 * c
        } else {
            1.055 * c.powf(1.0 / 2.4) - 0.055
        }
    }
}
