        "lch" => {
            let (l, c, h) = color.to_lch();
            format!("LCh({:.0}, {:.0}, {:.0})", l, c, h)
        }
        "oklch" => {
            let (l, c, h) = color.to_oklch();
            format!("OkLCh({:.4}, {:.4}, {:.4})", l, c, h)
        }
        "luminance" => format!("{:.3}", color.luminance()),
        "name" => {
            let mut min_dist = f64::MAX;
            let mut closest_name = "unknown";
            let (l1, a1, b1) = color.to_lab();
            for (name, rgb) in ALL_COLORS {
                let c = Color::from_rgb(rgb[0], rgb[1], rgb[2]);
                let (l2, a2, b2) = c.to_lab();
                let dist = ((l1-l2).powi(2) + (a1-a2).powi(2) + (b1-b2).powi(2)).sqrt();
                if dist < min_dist { min_dist = dist; closest_name = name; }
            }
            closest_name.to_string()
        }
        _ => format!(""),
    }
}

fn main() {
    let mut args: Vec<String> = env::args().collect();
    let mut i = 1;
    let mut color_mode = "auto".to_string();
    while i < args.len() {
        if args[i] == "-m" || args[i] == "--color-mode" {
            color_mode = args[i+1].clone(); args.remove(i); args.remove(i);
        } else if args[i] == "-f" || args[i] == "--force-color" {
            color_mode = "24bit".to_string(); args.remove(i);
        } else { i += 1; }
    }
    if args.len() < 2 { return; }
    let command = args[1].clone();
    let is_tty = io::stdout().is_terminal() || color_mode == "24bit";

    if command == "format" {
        let fmt = if args.len() > 2 { &args[2] } else { "hex" };
        let mut colors = Vec::new();
        if args.len() > 3 { colors = args[3..].to_vec(); }
        else { let stdin = io::stdin(); for l in stdin.lock().lines() { if let Ok(s) = l { colors.push(s); } } }
        for s in colors {
            for part in s.split_whitespace() {
               if let Some(c) = parse_color(part) { println!("{}", format_color(&c, fmt)); }
            }
        }
    } else if command == "color" {
        let mut colors = Vec::new();
        if args.len() > 2 { colors = args[2..].to_vec(); }
        else { let stdin = io::stdin(); for l in stdin.lock().lines() { if let Ok(s) = l { colors.push(s); } } }
        for s in colors {
            for part in s.split_whitespace() {
               if let Some(c) = parse_color(part) {
                   if is_tty {
                       println!("  Name: {}", format_color(&c, "name"));
                       println!("  Hex:  {}", format_color(&c, "hex"));
                       println!("  RGB:  {}", format_color(&c, "rgb"));
                       println!("  HSL:  {}", format_color(&c, "hsl"));
                   } else {
                       let (h, s, l) = c.to_hsl();
                       println!("hsl({:.0},{:.1}%,{:.1}%)", h, s * 100.0, l * 100.0);
                   }
               }
            }
        }
    } else if command == "list" {
        for (name, rgb) in ALL_COLORS {
            if is_tty {
                let fg = if (rgb[0] as f64 * 0.299 + rgb[1] as f64 * 0.587 + rgb[2] as f64 * 0.114) > 128.0 { "30" } else { "37" };
                println!("\x1b[{};48;2;{};{};{}m {:<23} \x1b[0m", fg, rgb[0], rgb[1], rgb[2], name);
            } else { println!("{}", name); }
        }
    } else if command == "gradient" {
        let mut n = 10;
        let mut i = 2;
        if i < args.len() && (args[i] == "-n" || args[i] == "--number") { n = args[i+1].parse().unwrap(); i += 2; }
        let mut colors = Vec::new();
        for j in i..args.len() { if let Some(c) = parse_color(&args[j]) { colors.push(c); } }
        if colors.len() >= 2 {
            for i in 0..n {
                let t = i as f64 / (n - 1) as f64;
                let idx = (t * (colors.len() - 1) as f64).floor() as usize;
                let next_idx = (idx + 1).min(colors.len() - 1);
                let local_t = if idx == next_idx { 0.0 } else { (t * (colors.len() - 1) as f64) - idx as f64 };
                let (l1, a1, b1) = colors[idx].to_lab();
                let (l2, a2, b2) = colors[next_idx].to_lab();
                let mixed = Color::from_lab(l1*(1.0-local_t)+l2*local_t, a1*(1.0-local_t)+a2*local_t, b1*(1.0-local_t)+b2*local_t);
                println!("{}", format_color(&mixed, "hex"));
            }
        }
    } else if command == "paint" {
        if let Some(color) = parse_color(&args[2]) {
            let (r, g, b, _) = color.to_rgba_u8();
            println!("\x1b[38;2;{};{};{}m{}\x1b[0m", r, g, b, args[3..].join(" "));
        }
    } else if ["lighten", "darken", "saturate", "desaturate", "complement", "rotate"].contains(&command.as_str()) {
        let mut amount = 0.0;
        let mut start_idx = 2;
        if command != "complement" { amount = args[2].parse().unwrap_or(0.0); start_idx = 3; }
        for j in start_idx..args.len() {
            if let Some(c) = parse_color(&args[j]) {
                let (h, s, l) = c.to_hsl();
                let mut nc = match command.as_str() {
                    "lighten" => Color::from_hsl(h, s, l + amount),
                    "darken" => Color::from_hsl(h, s, l - amount),
                    "saturate" => Color::from_hsl(h, s + amount, l),
                    "desaturate" => Color::from_hsl(h, s - amount, l),
                    "complement" => Color::from_hsl(h + 180.0, s, l),
                    "rotate" => Color::from_hsl(h + amount, s, l),
                    _ => c,
                };
                nc.a = c.a;
                println!("{}", format_color(&nc, "hex"));
            }
        }
    }
}
